with (O/'scalar_rows.csv').open() as f:raw=list(csv.DictReader(f))
ix=np.random.default_rng(0).integers(0,96,(2000,96));diff=[]
for c in s['cells']:
 seeds=(17,29,43) if c['seed']=='mean' else (c['seed'],);rr=[r for r in raw if int(r['seed']) in seeds and int(r['horizon'])==c['horizon']];pairs=sorted({r['pair'] for r in rr});assert len(pairs)==96
 for name,arm,metric,floor,absolute in [('feature_vs_recent','recent','feature_mse',.02,.01),('position_vs_recent','recent','position_mse',1e-5,1e-6),('feature_vs_current','current','feature_mse',.02,.01),('position_vs_current','current','position_mse',1e-5,1e-6)]:
  def vec(arm):return np.array([np.mean([float(r[metric]) for r in rr if r['arm']==arm and r['pair']==p]) for p in pairs])
  b,z=vec(arm),vec('candidate');useabs=b.mean()<floor
  effect=lambda x,y:(x-y if useabs else (x-y)/np.maximum(x,floor))
  v=float(effect(b.mean(),z.mean()));lo,hi=np.quantile(effect(b[ix].mean(1),z[ix].mean(1)),[.025,.975]);d=max(abs(v-c[name]['mean']),abs(lo-c[name]['low']),abs(hi-c[name]['high']));assert d<1e-11;diff.append(d)
(D/'local_review.json').write_text(json.dumps(dict(status='PASS',intervals=32,max_difference=max(diff)),indent=2)+'\n')
cs=[c for c in s['cells'] if c['seed']=='mean'];fig,ax=plt.subplots(figsize=(6,3.4),layout='constrained');vals=[100*c['feature_vs_current']['mean'] for c in cs];ax.bar(['3 steps','6 steps'],vals,color='.4',edgecolor='black');ax.axhline(0,color='black',ls='--');ax.set(ylabel='Feature-error reduction (%)',title='Frozen observed-anchor swap: validation')
for i,v in enumerate(vals):ax.annotate(f'{v:.2f}%',(i,v),ha='center',va='bottom' if v>=0 else 'top')
fig.savefig(D/'validation_result.png',dpi=160);plt.close(fig)
lines=['# Motion: observed-anchor cancellation validation','','## Why this is the next bounded check','','The preceding fixed endpoint ensemble improved ordinary validation but lost six original feature-effect checks under distractor shift. More averaging is not justified. Source inspection shows that shifted distractors are static within an episode and outside the arena, while the old reference still learns a scene-dependent recent-only forecast. Those observations motivate a common-anchor-error hypothesis; they do not prove that distractors are the sole cause.','','The candidate keeps the best frozen reference history increment, but changes its common anchor once:', '','`base = observed current feature + frozen train-only mean future residual + (best history forecast - best recent forecast)`','','Constrain this base to exactly the previous guarded historical decoded position using the same fixed output basis/readout. The coefficient is1; no grid or per-seed switch. The training mean is read from the original locked basis, never estimated on validation. Current observations, both forecasts, targets, decoder and basis are cached; this run performs no model/encoder forward, training or fitting. This differs from centering inputs to a frozen nonlinear predictor: the predictor is never called or modified.','','The hypothesis is falsifiable: if the historical increment is useful but the learned common anchor contributes appearance error, this fixed cancellation should improve full-feature error while preserving decoded position. If that decomposition is wrong, the validation screen rejects it. No held-out test is used to adjust the rule.','','## Data and results','','All96original validation pairs, both siblings,3seeds and horizons3/6:1,152complete prediction vectors and5,760scalar records. The same2historical and4recent observations are used. Future targets are scoring-only.','','![Validation improvement](../results/motion_anchor_swap_validation/validation_result.png)','','The vertical axis shows feature-error reduction relative to the previous best explored composite. Positive is better; negative means this repair worsens the forecast.','','| Check | Met / total |','|---|---:|',f"|Original feature numeric rule|{s['feature_checks']}/8|",f"|Original position numeric rule|{s['position_checks']}/8|",f"|Incremental feature paired lowerCI above0|{s['incremental_feature_positive']}/8|",'','The original numeric rules are unchanged. This conservative continuation screen also requires every incremental interval to have a positive lower bound before considering a full original recheck. That resource screen does not replace Phase1acceptance. Seed means reuse the same pairs.','','| Seed | Horizon | Feature reduction vs prior composite | Paired95%CI |','|---|---:|---:|---|']
for c in s['cells']:
 v=c['feature_vs_current'];lines.append(f"|{c['seed']}|{c['horizon']}|{100*v['mean']:.2f}%|[{100*v['low']:.2f}%,{100*v['high']:.2f}%]|")
lines+=['','## Independent audit','',f"All5,760scalar rows and32paired intervals were independently rebuilt. The current-query features are read again from the cache; an independent QR constraint reconstructs candidate vectors with maximum difference {a['vector_max_difference']:.3g}. Local32interval replay and compact native-before/local/native-after hashes also match.",'','## Decision','',f"**{s['status']}**.",'']
